using UnityEngine;
using UnityEngine.UI;
using TMPro;
using System.Collections.Generic;

namespace StoneThrowing
{
    public enum GameState
    {
        Menu,
        Picking,
        Aiming,
        Throwing,
        Flying,
        Splash,
        Result
    }

    public enum StoneType
    {
        Pebble,      // Đá cuội nhỏ
        Flat,        // Đá dẹt
        Round,       // Đá tròn
        Big,         // Đá lớn
        Colored      // Đá màu
    }

    [System.Serializable]
    public class StoneData
    {
        public StoneType type;
        public string displayName;
        public GameObject prefab;
        public float size;
        public float weight;
        public float bounciness;
        public float drag;
        public Color stoneColor;
        public Material material;
    }

    public class GameManager : MonoBehaviour
    {
        public static GameManager Instance { get; private set; }

        [Header("Game State")]
        public GameState currentState = GameState.Menu;

        [Header("Stone Settings")]
        public List<StoneData> stoneTypes = new List<StoneData>();
        public StoneData currentStone;
        public GameObject currentStoneInstance;
        public Transform stoneSpawnPoint;
        public Transform handTransform;

        [Header("Scoring")]
        public int totalThrows = 0;
        public int maxSkips = 0;
        public int currentSkips = 0;
        public float maxDistance = 0f;
        public int totalScore = 0;
        public TextMeshProUGUI scoreText;
        public TextMeshProUGUI distanceText;
        public TextMeshProUGUI skipsText;
        public TextMeshProUGUI throwsText;

        [Header("UI References")]
        public GameObject menuPanel;
        public GameObject hudPanel;
        public GameObject resultPanel;
        public GameObject pickUpButton;
        public GameObject throwButton;
        public GameObject resetButton;

        [Header("Camera")]
        public Camera mainCamera;
        public Transform followTarget;
        public float followSmoothTime = 0.1f;
        private Vector3 followVelocity = Vector3.zero;

        [Header("Audio")]
        public AudioSource ambienceSource;
        public AudioClip stoneFlyClip;
        public AudioClip waterSplashClip;
        public AudioClip waterRippleClip;
        public AudioClip stoneSinkClip;

        private float lastThrowTime = 0f;
        private bool isSlowMotion = false;

        void Awake()
        {
            if (Instance != null && Instance != this)
            {
                Destroy(gameObject);
                return;
            }
            Instance = this;
            DontDestroyOnLoad(gameObject);
        }

        void Start()
        {
            QualityManager.Instance.ApplyQualitySettings();
            AudioManager.Instance.PlayAmbience();
            ShowMenu();
            UpdateHUD();
        }

        void Update()
        {
            HandleStateInput();

            if (currentState == GameState.Flying && currentStoneInstance != null)
            {
                UpdateFlightTracking();
            }

            if (currentState == GameState.Splash && followTarget != null)
            {
                SmoothCameraFollow();
            }
        }

        void HandleStateInput()
        {
            if (Input.GetKeyDown(KeyCode.Escape))
            {
                if (currentState == GameState.Menu)
                    Application.Quit();
                else
                    ResetGame();
            }
        }

        void UpdateFlightTracking()
        {
            // Camera theo dõi viên đá khi bay
            if (followTarget != null && mainCamera != null)
            {
                Vector3 targetPos = followTarget.position + new Vector3(0, 2f, -3f);
                mainCamera.transform.position = Vector3.SmoothDamp(
                    mainCamera.transform.position, targetPos, ref followVelocity, followSmoothTime);
                mainCamera.transform.LookAt(followTarget);
            }

            // Kiểm tra đá đã dừng hoặc chìm
            Rigidbody rb = currentStoneInstance.GetComponent<Rigidbody>();
            if (rb != null && rb.velocity.magnitude < 0.1f && rb.IsSleeping())
            {
                EndThrow();
            }
        }

        void SmoothCameraFollow()
        {
            if (followTarget != null && mainCamera != null)
            {
                Vector3 targetPos = followTarget.position + new Vector3(0, 1.5f, -2f);
                mainCamera.transform.position = Vector3.SmoothDamp(
                    mainCamera.transform.position, targetPos, ref followVelocity, followSmoothTime);
            }
        }

        public void StartPicking()
        {
            currentState = GameState.Picking;
            pickUpButton.SetActive(false);
            throwButton.SetActive(false);
            hudPanel.SetActive(true);
            menuPanel.SetActive(false);

            // Tạo bàn tay 3D
            if (handTransform != null)
                handTransform.gameObject.SetActive(true);

            Debug.Log("Đang chờ người chơi nhặt đá...");
        }

        public void OnStonePicked(GameObject stoneObj, StoneData data)
        {
            currentStoneInstance = stoneObj;
            currentStone = data;
            currentState = GameState.Aiming;
            throwButton.SetActive(true);

            // Cập nhật camera nhìn về tay cầm đá
            if (handTransform != null && mainCamera != null)
            {
                Vector3 handPos = handTransform.position;
                Vector3 camPos = handPos + new Vector3(0, 0.5f, -0.8f);
                mainCamera.transform.position = camPos;
                mainCamera.transform.LookAt(handPos);
            }

            Debug.Log($"Đã nhặt: {data.displayName} (Trọng lượng: {data.weight})");
        }

        public void ThrowStone(Vector3 direction, float force)
        {
            if (currentStoneInstance == null || currentState != GameState.Aiming)
                return;

            currentState = GameState.Throwing;
            totalThrows++;
            UpdateHUD();

            Rigidbody rb = currentStoneInstance.GetComponent<Rigidbody>();
            if (rb != null)
            {
                rb.isKinematic = false;
                rb.useGravity = true;
                rb.drag = currentStone.drag;
                rb.mass = currentStone.weight;
                rb.AddForce(direction * force, ForceMode.Impulse);

                // Thêm xoay ngẫu nhiên cho viên đá
                rb.AddTorque(Random.insideUnitSphere * 5f, ForceMode.Impulse);

                // Phát âm thanh đá bay
                AudioManager.Instance.PlayStoneFly();

                // Bật motion blur
                QualityManager.Instance.EnableMotionBlur(true);
            }

            followTarget = currentStoneInstance.transform;
            currentState = GameState.Flying;
            lastThrowTime = Time.time;
        }

        public void OnStoneHitWater(Vector3 impactPoint, float impactForce)
        {
            if (currentState != GameState.Flying)
                return;

            currentState = GameState.Splash;

            // Kích hoạt VFX 2.0
            WaterVFXManager.Instance.TriggerAllVFX(impactPoint, impactForce, currentStone);

            // Phát âm thanh nước
            AudioManager.Instance.PlayWaterSplash(impactPoint);

            // Kích hoạt slow motion nếu lực va chạm lớn
            if (impactForce > 15f)
            {
                StartSlowMotion(0.3f, 1f);
            }

            // Theo dõi viên đá trong nước
            if (currentStoneInstance != null)
            {
                followTarget = currentStoneInstance.transform;
                Invoke(nameof(CheckStoneInWater), 1f);
            }
        }

        void CheckStoneInWater()
        {
            if (currentStoneInstance != null)
            {
                StonePhysics stonePhys = currentStoneInstance.GetComponent<StonePhysics>();
                if (stonePhys != null && stonePhys.IsInWater)
                {
                    AudioManager.Instance.PlayStoneSink();
                    WaterVFXManager.Instance.SpawnBubbles(currentStoneInstance.transform.position);
                }
            }
        }

        public void OnStoneSkip()
        {
            currentSkips++;
            if (currentSkips > maxSkips)
                maxSkips = currentSkips;
            UpdateHUD();
            AudioManager.Instance.PlayWaterRipple();
        }

        void EndThrow()
        {
            currentState = GameState.Result;
            if (currentStoneInstance != null)
            {
                float dist = Vector3.Distance(stoneSpawnPoint.position, currentStoneInstance.transform.position);
                if (dist > maxDistance)
                    maxDistance = dist;

                int throwScore = Mathf.RoundToInt(dist * 10f + currentSkips * 50f);
                totalScore += throwScore;
            }
            UpdateHUD();

            throwButton.SetActive(false);
            resetButton.SetActive(true);

            // Tắt motion blur
            QualityManager.Instance.EnableMotionBlur(false);
        }

        public void ResetGame()
        {
            currentState = GameState.Menu;
            currentSkips = 0;
            totalThrows = 0;

            if (currentStoneInstance != null)
            {
                Destroy(currentStoneInstance);
                currentStoneInstance = null;
            }

            if (handTransform != null)
                handTransform.gameObject.SetActive(false);

            followTarget = null;
            isSlowMotion = false;
            Time.timeScale = 1f;

            ShowMenu();
            UpdateHUD();

            QualityManager.Instance.EnableMotionBlur(false);
        }

        public void ShowMenu()
        {
            menuPanel.SetActive(true);
            hudPanel.SetActive(false);
            resultPanel.SetActive(false);
            pickUpButton.SetActive(true);
            throwButton.SetActive(false);
            resetButton.SetActive(false);
        }

        public void ShowResult()
        {
            resultPanel.SetActive(true);
            hudPanel.SetActive(false);
        }

        void UpdateHUD()
        {
            if (scoreText != null) scoreText.text = "ĐIỂM: " + totalScore;
            if (distanceText != null) distanceText.text = "KHOẢNG CÁCH: " + maxDistance.ToString("F1") + " m";
            if (skipsText != null) skipsText.text = "LẦN NẤY: " + currentSkips;
            if (throwsText != null) throwsText.text = "LẦN NÉM: " + totalThrows;
        }

        public void StartSlowMotion(float scale, float duration)
        {
            isSlowMotion = true;
            Time.timeScale = scale;
            Time.fixedDeltaTime = 0.02f * Time.timeScale;
            Invoke(nameof(EndSlowMotion), duration);
        }

        void EndSlowMotion()
        {
            isSlowMotion = false;
            Time.timeScale = 1f;
            Time.fixedDeltaTime = 0.02f;
        }

        public float GetStoneWeight() => currentStone != null ? currentStone.weight : 1f;
        public float GetStoneSize() => currentStone != null ? currentStone.size : 0.5f;
    }
}

using UnityEngine;
using UnityEngine.EventSystems;
using System.Collections;

namespace StoneThrowing
{
    public class StonePicker : MonoBehaviour
    {
        [Header("Pick Settings")]
        public LayerMask stoneLayer;
        public LayerMask groundLayer;
        public float pickDistance = 5f;
        public Transform handParent;
        public Animator handAnimator;
        public float pickUpDuration = 0.5f;

        [Header("Hand Animation")]
        public float fingerCurlSpeed = 2f;
        public float wristRotateSpeed = 2f;
        public Vector3 holdPosition = new Vector3(0.1f, -0.05f, 0.15f);
        public Vector3 holdRotation = new Vector3(10f, 0f, 0f);

        private GameObject hoveredStone;
        private GameObject heldStone;
        private StoneThrowing.StoneData heldStoneData;
        private bool isPicking = false;
        private Vector3 originalStonePos;
        private Quaternion originalStoneRot;

        void Update()
        {
            if (GameManager.Instance.currentState != GameState.Picking)
                return;

            if (Input.touchCount > 0 && Input.GetTouch(0).phase == TouchPhase.Began)
            {
                if (EventSystem.current.IsPointerOverGameObject(Input.GetTouch(0).fingerId))
                    return;

                Ray ray = Camera.main.ScreenPointToRay(Input.GetTouch(0).position);
                HandlePickRaycast(ray);
            }

            if (Input.GetMouseButtonDown(0))
            {
                if (EventSystem.current.IsPointerOverGameObject())
                    return;

                Ray ray = Camera.main.ScreenPointToRay(Input.mousePosition);
                HandlePickRaycast(ray);
            }

            UpdateHandAnimation();
        }

        void HandlePickRaycast(Ray ray)
        {
            if (Physics.Raycast(ray, out RaycastHit hit, pickDistance, stoneLayer))
            {
                StoneData stoneData = hit.collider.GetComponent<StoneData>();
                if (stoneData != null)
                {
                    PickUpStone(hit.collider.gameObject, stoneData);
                }
            }
        }

        void PickUpStone(GameObject stoneObj, StoneData data)
        {
            if (isPicking) return;
            isPicking = true;

            heldStone = stoneObj;
            heldStoneData = data;
            originalStonePos = stoneObj.transform.position;
            originalStoneRot = stoneObj.transform.rotation;

            // Hiệu ứng nhặt mượt
            StartCoroutine(PickUpCoroutine(stoneObj, data));
        }

        IEnumerator PickUpCoroutine(GameObject stoneObj, StoneData data)
        {
            float elapsed = 0f;
            Rigidbody rb = stoneObj.GetComponent<Rigidbody>();
            if (rb != null)
                rb.isKinematic = true;

            // Animation ngón tay co lại
            if (handAnimator != null)
                handAnimator.SetTrigger("Grab");

            while (elapsed < pickUpDuration)
            {
                elapsed += Time.deltaTime;
                float t = elapsed / pickUpDuration;
                t = t * t * (3f - 2f * t); // Smoothstep

                if (stoneObj != null && handParent != null)
                {
                    stoneObj.transform.position = Vector3.Lerp(originalStonePos,
                        handParent.position + handParent.TransformVector(holdPosition), t);
                    stoneObj.transform.rotation = Quaternion.Lerp(originalStoneRot,
                        handParent.rotation * Quaternion.Euler(holdRotation), t);
                    stoneObj.transform.localScale = Vector3.one * data.size;
                }
                yield return null;
            }

            // Gán đá vào tay
            if (stoneObj != null && handParent != null)
            {
                stoneObj.transform.SetParent(handParent);
                stoneObj.transform.localPosition = holdPosition;
                stoneObj.transform.localRotation = Quaternion.Euler(holdRotation);
            }

            // Thông báo cho GameManager
            GameManager.Instance.OnStonePicked(stoneObj, data);
            isPicking = false;
        }

        void UpdateHandAnimation()
        {
            if (handAnimator == null) return;

            if (heldStone != null)
            {
                // Cầm nắm tự nhiên
                float curl = Mathf.Lerp(handAnimator.GetFloat("FingerCurl"), 1f, Time.deltaTime * fingerCurlSpeed);
                handAnimator.SetFloat("FingerCurl", curl);

                // Xoay cổ tay nhẹ theo di chuyển
                float wristX = Mathf.Sin(Time.time * wristRotateSpeed) * 5f;
                handAnimator.SetFloat("WristRotation", wristX);
            }
            else
            {
                float curl = Mathf.Lerp(handAnimator.GetFloat("FingerCurl"), 0f, Time.deltaTime * fingerCurlSpeed);
                handAnimator.SetFloat("FingerCurl", curl);
            }
        }

        public void DropStone()
        {
            if (heldStone != null && handParent != null)
            {
                heldStone.transform.SetParent(null);
                Rigidbody rb = heldStone.GetComponent<Rigidbody>();
                if (rb != null)
                    rb.isKinematic = false;

                heldStone = null;
                heldStoneData = null;
            }
        }

        public StoneData GetHeldStoneData() => heldStoneData;
    }
}

using UnityEngine;
using UnityEngine.EventSystems;
using UnityEngine.UI;

namespace StoneThrowing
{
    public class StoneThrower : MonoBehaviour
    {
        [Header("Throw Settings")]
        public float minThrowForce = 5f;
        public float maxThrowForce = 40f;
        public float forceMultiplier = 2f;
        public float maxSwipeTime = 1f;
        public float minSwipeDistance = 10f;
        public LayerMask waterLayer;
        public Transform aimLineOrigin;
        public LineRenderer aimLine;

        [Header("UI")]
        public Slider powerSlider;
        public GameObject powerSliderUI;
        public TextMeshProUGUI powerText;

        private Vector2 touchStartPos;
        private Vector2 touchEndPos;
        private float touchStartTime;
        private bool isDragging = false;
        private bool canThrow = false;

        void Update()
        {
            if (GameManager.Instance.currentState != GameState.Aiming)
            {
                HideAimLine();
                powerSliderUI.SetActive(false);
                return;
            }

            HandleTouchInput();

            if (isDragging)
            {
                UpdateAimLine();
                UpdatePowerUI();
            }
        }

        void HandleTouchInput()
        {
            if (Input.touchCount > 0)
            {
                Touch touch = Input.GetTouch(0);

                if (EventSystem.current.IsPointerOverGameObject(touch.fingerId))
                    return;

                switch (touch.phase)
                {
                    case TouchPhase.Began:
                        touchStartPos = touch.position;
                        touchEndPos = touch.position;
                        touchStartTime = Time.time;
                        isDragging = true;
                        canThrow = false;
                        powerSliderUI.SetActive(true);
                        break;

                    case TouchPhase.Moved:
                    case TouchPhase.Stationary:
                        touchEndPos = touch.position;
                        break;

                    case TouchPhase.Ended:
                        if (isDragging && Time.time - touchStartTime <= maxSwipeTime)
                        {
                            PerformThrow();
                        }
                        isDragging = false;
                        canThrow = false;
                        powerSliderUI.SetActive(false);
                        HideAimLine();
                        break;
                }
            }

            // Hỗ trợ phím để test trên PC
            if (Input.GetMouseButtonDown(0))
            {
                if (EventSystem.current.IsPointerOverGameObject()) return;
                touchStartPos = Input.mousePosition;
                touchEndPos = Input.mousePosition;
                touchStartTime = Time.time;
                isDragging = true;
                powerSliderUI.SetActive(true);
            }

            if (Input.GetMouseButton(0) && isDragging)
            {
                touchEndPos = Input.mousePosition;
            }

            if (Input.GetMouseButtonUp(0) && isDragging)
            {
                if (Time.time - touchStartTime <= maxSwipeTime)
                {
                    PerformThrow();
                }
                isDragging = false;
                canThrow = false;
                powerSliderUI.SetActive(false);
                HideAimLine();
            }
        }

        void UpdateAimLine()
        {
            Vector2 swipe = touchEndPos - touchStartPos;
            if (swipe.magnitude < minSwipeDistance)
            {
                HideAimLine();
                return;
            }

            Vector3 dir = GetThrowDirection(swipe);
            float force = CalculateForce(swipe);

            if (aimLine != null && aimLineOrigin != null)
            {
                aimLine.positionCount = 2;
                aimLine.SetPosition(0, aimLineOrigin.position);
                Vector3 endPos = aimLineOrigin.position + dir * (force * 0.1f);
                aimLine.SetPosition(1, endPos);
                aimLine.enabled = true;
            }
        }

        void UpdatePowerUI()
        {
            Vector2 swipe = touchEndPos - touchStartPos;
            float force = CalculateForce(swipe);
            float normalized = Mathf.InverseLerp(minThrowForce, maxThrowForce, force);

            if (powerSlider != null)
                powerSlider.value = normalized;

            if (powerText != null)
                powerText.text = $"LỰC NÉM: {force:F1}";
        }

        void PerformThrow()
        {
            if (!canThrow)
            {
                Vector2 swipe = touchEndPos - touchStartPos;
                if (swipe.magnitude < minSwipeDistance) return;

                float force = CalculateForce(swipe);
                Vector3 direction = GetThrowDirection(swipe);

                GameManager.Instance.ThrowStone(direction, force);
                canThrow = true;
            }
        }

        Vector3 GetThrowDirection(Vector2 swipe)
        {
            // Chuyển vector vuốt 2D thành hướng 3D theo camera
            Camera cam = Camera.main;
            Vector3 forward = cam.transform.forward;
            forward.y = 0f;
            forward.Normalize();

            Vector3 right = cam.transform.right;
            right.y = 0f;
            right.Normalize();

            float swipeX = swipe.x / Screen.width;
            float swipeY = swipe.y / Screen.height;

            Vector3 dir = forward * swipeY + right * swipeX;
            dir.y = Mathf.Clamp01(swipeY * 0.5f + 0.5f); // Hướng lên trên khi vuốt lên
            dir.Normalize();

            return dir;
        }

        float CalculateForce(Vector2 swipe)
        {
            float distance = swipe.magnitude;
            float time = Mathf.Max(Time.time - touchStartTime, 0.01f);
            float speed = distance / time;

            float force = Mathf.Clamp(speed * forceMultiplier * 0.1f, minThrowForce, maxThrowForce);
            return force;
        }

        void HideAimLine()
        {
            if (aimLine != null)
                aimLine.enabled = false;
        }

        public void OnThrowButtonPressed()
        {
            if (GameManager.Instance.currentState == GameState.Aiming)
            {
                // Ném với lực mặc định từ slider
                float force = Mathf.Lerp(minThrowForce, maxThrowForce,
                    powerSlider != null ? powerSlider.value : 0.5f);
                Vector3 dir = Camera.main.transform.forward;
                dir.y = 0.5f;
                dir.Normalize();
                GameManager.Instance.ThrowStone(dir, force);
            }
        }
    }
}

using UnityEngine;

namespace StoneThrowing
{
    [RequireComponent(typeof(Rigidbody))]
    public class StonePhysics : MonoBehaviour
    {
        [Header("Physics")]
        public float waterDrag = 2f;
        public float airDrag = 0.1f;
        public float skipForceMultiplier = 0.6f;
        public float minSkipVelocity = 2f;
        public float sinkSpeed = 3f;

        [Header("Visual")]
        public TrailRenderer stoneTrail;
        public ParticleSystem wakeParticles;
        public ParticleSystem bubbleParticles;

        [Header("Audio")]
        public AudioSource stoneAudioSource;
        public AudioClip skipSound;
        public AudioClip sinkSound;

        public bool IsInWater { get; private set; }
        public bool IsSinking { get; private set; }

        private Rigidbody rb;
        private Collider stoneCollider;
        private bool hasEnteredWater = false;
        private float waterEntryTime = 0f;
        private Vector3 lastVelocity;
        private int skipCount = 0;

        void Awake()
        {
            rb = GetComponent<Rigidbody>();
            stoneCollider = GetComponent<Collider>();

            if (stoneTrail != null)
                stoneTrail.enabled = true;

            if (wakeParticles != null)
                wakeParticles.Play();
        }

        void FixedUpdate()
        {
            if (rb == null) return;

            lastVelocity = rb.velocity;

            // Lực cản không khí khi bay
            if (!IsInWater)
            {
                rb.drag = airDrag;

                // Xoay viên đá theo hướng bay
                if (rb.velocity.magnitude > 1f)
                {
                    Quaternion targetRot = Quaternion.LookRotation(rb.velocity);
                    rb.MoveRotation(Quaternion.Slerp(rb.rotation, targetRot, Time.fixedDeltaTime * 5f));
                }
            }
        }

        void OnTriggerEnter(Collider other)
        {
            if ((GameManager.Instance.waterLayer.value & (1 << other.gameObject.layer)) != 0)
            {
                EnterWater();
            }
        }

        void OnTriggerStay(Collider other)
        {
            if ((GameManager.Instance.waterLayer.value & (1 << other.gameObject.layer)) != 0)
            {
                ApplyWaterPhysics();
            }
        }

        void OnTriggerExit(Collider other)
        {
            if ((GameManager.Instance.waterLayer.value & (1 << other.gameObject.layer)) != 0)
            {
                ExitWater();
            }
        }

        void EnterWater()
        {
            IsInWater = true;
            hasEnteredWater = true;
            waterEntryTime = Time.time;

            // Thông báo VFX
            if (GameManager.Instance.currentStoneInstance == gameObject)
            {
                float impactForce = rb.velocity.magnitude;
                Vector3 impactPoint = transform.position;
                GameManager.Instance.OnStoneHitWater(impactPoint, impactForce);
            }

            // Giảm drag ngay khi vào nước
            if (rb != null)
                rb.drag = waterDrag;

            Debug.Log("Đá chạm mặt nước!");
        }

        void ApplyWaterPhysics()
        {
            if (rb == null) return;

            // Áp lực nổi đơn giản
            Vector3 buoyancy = Vector3.up * 9.81f * rb.mass * 0.5f;
            rb.AddForce(buoyancy, ForceMode.Acceleration);

            // Drag trong nước cao hơn
            rb.drag = Mathf.Lerp(rb.drag, waterDrag, Time.fixedDeltaTime * 5f);

            // Nếu chậm trong nước, bắt đầu chìm
            if (rb.velocity.magnitude < minSkipVelocity && Time.time - waterEntryTime > 0.5f)
            {
                StartSinking();
            }
        }

        void StartSinking()
        {
            if (IsSinking) return;
            IsSinking = true;

            if (rb != null)
            {
                rb.useGravity = false;
                rb.velocity = Vector3.zero;
                rb.angularVelocity = Vector3.zero;
            }

            StartCoroutine(SinkCoroutine());
        }

        IEnumerator SinkCoroutine()
        {
            while (transform.position.y > -10f)
            {
                transform.position += Vector3.down * sinkSpeed * Time.deltaTime;

                // Bọt khí khi chìm
                if (bubbleParticles != null && Random.value < 0.3f)
                {
                    bubbleParticles.Emit(1);
                }

                yield return null;
            }

            // Kết thúc vụ ném
            GameManager.Instance.EndThrow();
        }

        void ExitWater()
        {
            IsInWater = false;
            if (rb != null)
                rb.drag = airDrag;
        }

        // Kiểm tra nảy trên mặt nước (skip)
        public void CheckWaterSkip(Vector3 hitPoint, Vector3 hitNormal)
        {
            if (!IsInWater || IsSinking) return;

            float velocityY = Mathf.Abs(rb.velocity.y);
            float stoneWeight = GameManager.Instance.GetStoneWeight();

            // Đá dẹt, nhẹ, vitesse cao -> nảy dễ hơn
            float skipChance = (1f / stoneWeight) * (velocityY / 10f);
            if (Random.value < skipChance * 0.5f && velocityY > minSkipVelocity)
            {
                PerformSkip(hitNormal);
            }
        }

        void PerformSkip(Vector3 normal)
        {
            if (rb == null) return;

            skipCount++;
            GameManager.Instance.OnStoneSkip();

            // Phản xạ velocità
            Vector3 reflect = Vector3.Reflect(rb.velocity, normal);
            reflect.y = Mathf.Abs(reflect.y) * skipForceMultiplier;
            reflect.x *= skipForceMultiplier;
            reflect.z *= skipForceMultiplier;

            rb.velocity = reflect;
            rb.AddForce(Vector3.up * 5f, ForceMode.Impulse);

            // Phát âm thanh nảy
            if (stoneAudioSource != null && skipSound != null)
                stoneAudioSource.PlayOneShot(skipSound);

            // VFX nước nhỏ tại điểm nảy
            WaterVFXManager.Instance.SpawnSmallSplash(transform.position, 0.3f);

            Debug.Log($"Lần nảy {skipCount}");
        }

        void OnCollisionEnter(Collision collision)
        {
            // Va chạm với mặt nước (nếu dùng collider thay vì trigger)
            if ((GameManager.Instance.waterLayer.value & (1 << collision.gameObject.layer)) != 0)
            {
                ContactPoint contact = collision.contacts[0];
                CheckWaterSkip(contact.point, contact.normal);
            }
        }
    }
}

using UnityEngine;
using System.Collections.Generic;

namespace StoneThrowing
{
    public class WaterVFXManager : MonoBehaviour
    {
        public static WaterVFXManager Instance { get; private set; }

        [Header("Splash VFX")]
        public GameObject splashPrefab;
        public int splashParticleCount = 50;
        public float splashForce = 10f;
        public float splashRadius = 1f;

        [Header("Ripple VFX")]
        public GameObject ripplePrefab;
        public int maxRipples = 8;
        public float rippleSpeed = 5f;
        public float rippleDuration = 3f;

        [Header("Droplets VFX")]
        public GameObject dropletPrefab;
        public int dropletCount = 100;
        public float dropletHeight = 5f;
        public float dropletLife = 2f;

        [Header("Foam VFX")]
        public GameObject foamPrefab;
        public float foamRadius = 1.5f;
        public float foamDuration = 4f;

        [Header("Water Distortion")]
        public Material distortionMaterial;
        public float distortionStrength = 0.1f;
        public float distortionDuration = 1f;

        [Header("Slow Motion")]
        public bool enableSlowMotion = true;
        public float slowMotionScale = 0.25f;
        public float slowMotionDuration = 1f;

        [Header("Motion Blur")]
        public bool enableMotionBlur = true;

        private List<GameObject> activeRipples = new List<GameObject>();
        private GameObject distortionInstance;

        void Awake()
        {
            if (Instance != null && Instance != this)
            {
                Destroy(gameObject);
                return;
            }
            Instance = this;
        }

        void Start()
        {
            // Tối ưu particle pool
            InitializeParticlePools();
        }

        void InitializeParticlePools()
        {
            // Pré-instantiate để tránh lag khi spawn
        }

        public void TriggerAllVFX(Vector3 impactPoint, float impactForce, StoneData stoneData)
        {
            // Điều chỉnh các tham số dựa trên loại đá và lực va chạm
            float forceMultiplier = impactForce / 20f;
            int dropletAmount = Mathf.RoundToInt(dropletCount * forceMultiplier);
            float splashSize = Mathf.Clamp(forceMultiplier, 0.5f, 2f);

            // 1. VFX Splash - nước bắn tung lên
            SpawnSplash(impactPoint, splashSize);

            // 2. VFX Ripple - vòng sóng tròn
            SpawnRipple(impactPoint, splashSize);

            // 3. VFX Droplets - giọt nước bay lên rồi rơi
            SpawnDroplets(impactPoint, dropletAmount);

            // 4. VFX Foam - bọt nước
            SpawnFoam(impactPoint);

            // 5. VFX Water Distortion - biến dạng mặt nước
            StartCoroutine(WaterDistortionEffect(impactPoint, distortionStrength * forceMultiplier));

            // 6. VFX Slow Motion - quay chậm
            if (enableSlowMotion && GameManager.Instance != null)
            {
                GameManager.Instance.StartSlowMotion(slowMotionScale, slowMotionDuration);
            }

            // 7. VFX Motion Blur
            if (enableMotionBlur && QualityManager.Instance != null)
            {
                QualityManager.Instance.EnableMotionBlur(true);
                Invoke(nameof(DisableMotionBlur), 1f);
            }

            Debug.Log($"VFX 2.0 kích hoạt tại {impactPoint} với lực {impactForce:F1}");
        }

        void SpawnSplash(Vector3 position, float size)
        {
            if (splashPrefab == null) return;

            GameObject splash = Instantiate(splashPrefab, position, Quaternion.identity);
            ParticleSystem ps = splash.GetComponent<ParticleSystem>();
            if (ps != null)
            {
                var main = ps.main;
                main.startSize = 0.5f * size;
                main.startSpeed = splashForce * size;
                main.maxParticles = splashParticleCount;
            }
            Destroy(splash, 3f);
        }

        void SpawnRipple(Vector3 position, float size)
        {
            if (ripplePrefab == null) return;

            // Tối ưu: giới hạn số ripple đồng thời
            while (activeRipples.Count >= maxRipples)
            {
                GameObject old = activeRipples[0];
                activeRipples.RemoveAt(0);
                if (old != null) Destroy(old);
            }

            GameObject ripple = Instantiate(ripplePrefab, position, Quaternion.identity);
            activeRipples.Add(ripple);

            WaterRipple rippleScript = ripple.AddComponent<WaterRipple>();
            rippleScript.Initialize(position, rippleSpeed, rippleDuration, size);
            Destroy(ripple, rippleDuration);
        }

        void SpawnDroplets(Vector3 position, int count)
        {
            if (dropletPrefab == null) return;

            for (int i = 0; i < count; i++)
            {
                Vector3 randomDir = Random.insideUnitSphere.normalized;
                randomDir.y = Mathf.Abs(randomDir.y) * 0.5f + 0.5f;
                Vector3 spawnPos = position + randomDir * 0.5f;

                GameObject droplet = Instantiate(dropletPrefab, spawnPos, Quaternion.identity);
                Rigidbody rb = droplet.GetComponent<Rigidbody>();
                if (rb != null)
                {
                    rb.AddForce(randomDir * Random.Range(2f, 8f), ForceMode.Impulse);
                    rb.AddTorque(Random.insideUnitSphere, ForceMode.Impulse);
                }
                Destroy(droplet, dropletLife);
            }
        }

        void SpawnFoam(Vector3 position)
        {
            if (foamPrefab == null) return;

            GameObject foam = Instantiate(foamPrefab, position, Quaternion.identity);
            Destroy(foam, foamDuration);
        }

        public void SpawnSmallSplash(Vector3 position, float scale)
        {
            if (splashPrefab == null) return;
            GameObject splash = Instantiate(splashPrefab, position, Quaternion.identity);
            ParticleSystem ps = splash.GetComponent<ParticleSystem>();
            if (ps != null)
            {
                var main = ps.main;
                main.startSize = 0.2f * scale;
                main.startSpeed = 5f * scale;
                main.maxParticles = 15;
            }
            Destroy(splash, 2f);
        }

        public void SpawnBubbles(Vector3 position)
        {
            if (bubbleParticles == null) return;
            // Bubbles handled in StonePhysics, but can add here
            var emitter = bubbleParticles.GetComponent<ParticleSystem>();
            if (emitter != null)
            {
                emitter.transform.position = position;
                emitter.Emit(20);
            }
        }

        System.Collections.IEnumerator WaterDistortionEffect(Vector3 position, float strength)
        {
            if (distortionMaterial == null) yield break;

            // Tạo distortion mesh hoặc shader effect tại vị trí va chạm
            GameObject distortionObj = new GameObject("WaterDistortion");
            distortionObj.transform.position = position;
            MeshRenderer mr = distortionObj.AddComponent<MeshRenderer>();
            MeshFilter mf = distortionObj.AddComponent<MeshFilter>();
            mf.mesh = CreateDistortionMesh();
            mr.material = distortionMaterial;

            float elapsed = 0f;
            Color startColor = distortionMaterial.color;
            while (elapsed < distortionDuration)
            {
                elapsed += Time.deltaTime;
                float t = elapsed / distortionDuration;
                distortionMaterial.SetFloat("_DistortionStrength", Mathf.Lerp(strength, 0f, t));
                distortionMaterial.color = Color.Lerp(startColor, Color.clear, t);
                yield return null;
            }

            Destroy(distortionObj);
        }

        Mesh CreateDistortionMesh()
        {
            Mesh mesh = new Mesh();
            Vector3[] vertices = new Vector3[4];
            Vector2[] uv = new Vector2[4];
            int[] triangles = new int[6];

            float s = 1f;
            vertices[0] = new Vector3(-s, 0, -s);
            vertices[1] = new Vector3(s, 0, -s);
            vertices[2] = new Vector3(s, 0, s);
            vertices[3] = new Vector3(-s, 0, s);

            uv[0] = new Vector2(0, 0);
            uv[1] = new Vector2(1, 0);
            uv[2] = new Vector2(1, 1);
            uv[3] = new Vector2(0, 1);

            triangles[0] = 0; triangles[1] = 1; triangles[2] = 2;
            triangles[3] = 0; triangles[4] = 2; triangles[5] = 3;

            mesh.vertices = vertices;
            mesh.uv = uv;
            mesh.triangles = triangles;
            mesh.RecalculateNormals();
            return mesh;
        }

        void DisableMotionBlur()
        {
            if (QualityManager.Instance != null)
                QualityManager.Instance.EnableMotionBlur(false);
        }
    }

    public class WaterRipple : MonoBehaviour
    {
        private Vector3 center;
        private float speed;
        private float duration;
        private float size;
        private float elapsed = 0f;
        private Material rippleMaterial;

        public void Initialize(Vector3 centerPos, float rippleSpeed, float rippleDuration, float rippleSize)
        {
            center = centerPos;
            speed = rippleSpeed;
            duration = rippleDuration;
            size = rippleSize;

            rippleMaterial = new Material(Shader.Find("Custom/WaterRipple"));
            GetComponent<MeshRenderer>().material = rippleMaterial;
        }

        void Update()
        {
            elapsed += Time.deltaTime;
            float t = elapsed / duration;

            if (rippleMaterial != null)
            {
                float radius = t * speed * 10f;
                rippleMaterial.SetFloat("_Radius", radius);
                rippleMaterial.SetFloat("_Opacity", 1f - t);
                rippleMaterial.SetVector("_Center", center);
            }

            transform.localScale = Vector3.one * (1f + t * 5f);

            if (t >= 1f)
            {
                Destroy(gameObject);
            }
        }
    }
}

