using UnityEngine;
using System.Collections.Generic;

namespace StoneThrowing
{
    public class AudioManager : MonoBehaviour
    {
        public static AudioManager Instance { get; private set; }

        [Header("Ambience")]
        public AudioSource ambienceSource;
        public AudioClip birdsClip;
        public AudioClip windClip;
        public AudioClip waterClip;

        [Header("SFX")]
        public AudioSource sfxSource;
        public AudioClip stoneFlyClip;
        public AudioClip waterSplashClip;
        public AudioClip waterRippleClip;
        public AudioClip stoneSinkClip;
        public AudioClip stoneSkipClip;

        [Header("3D Audio")]
        public AudioSource spatialSource;
        public float spatialVolume = 1f;

        private bool isMuted = false;
        private float masterVolume = 1f;

        void Awake()
        {
            if (Instance != null && Instance != this)
            {
                Destroy(gameObject);
                return;
            }
            Instance = this;
            DontDestroyOnLoad(gameObject);
        }

        void Start()
        {
            PlayAmbience();
        }

        public void PlayAmbience()
        {
            if (ambienceSource == null) return;

            ambienceSource.loop = true;
            ambienceSource.volume = masterVolume * 0.5f;

            // Phát trộn các âm thanh môi trường
            if (birdsClip != null)
            {
                AudioSource birds = gameObject.AddComponent<AudioSource>();
                birds.clip = birdsClip;
                birds.loop = true;
                birds.volume = masterVolume * 0.3f;
                birds.Play();
            }

            if (windClip != null)
            {
                AudioSource wind = gameObject.AddComponent<AudioSource>();
                wind.clip = windClip;
                wind.loop = true;
                wind.volume = masterVolume * 0.2f;
                wind.Play();
            }

            if (waterClip != null)
            {
                ambienceSource.clip = waterClip;
                ambienceSource.Play();
            }
        }

        public void PlayStoneFly()
        {
            if (isMuted) return;
            PlaySpatialSFX(stoneFlyClip, 0.6f);
        }

        public void PlayWaterSplash(Vector3 position)
        {
            if (isMuted) return;
            PlaySpatialSFX(waterSplashClip, 1f, position);
        }

        public void PlayWaterRipple()
        {
            if (isMuted) return;
            PlaySFX(waterRippleClip, 0.4f);
        }

        public void PlayStoneSink()
        {
            if (isMuted) return;
            PlaySpatialSFX(stoneSinkClip, 0.8f);
        }

        public void PlayStoneSkip()
        {
            if (isMuted) return;
            PlaySFX(stoneSkipClip, 0.5f);
        }

        void PlaySFX(AudioClip clip, float volume)
        {
            if (clip == null || sfxSource == null) return;
            sfxSource.PlayOneShot(clip, volume * masterVolume);
        }

        void PlaySpatialSFX(AudioClip clip, float volume, Vector3? position = null)
        {
            if (clip == null) return;

            GameObject go = new GameObject("TempAudio");
            if (position.HasValue)
                go.transform.position = position.Value;

            AudioSource source = go.AddComponent<AudioSource>();
            source.clip = clip;
            source.volume = volume * masterVolume;
            source.spatialBlend = 1f; // 3D sound
            source.dopplerLevel = 0.1f;
            source.Play();

            Destroy(go, clip.length);
        }

        public void ToggleMute()
        {
            isMuted = !isMuted;
            AudioListener.volume = isMuted ? 0f : masterVolume;
        }

        public void SetMasterVolume(float volume)
        {
            masterVolume = Mathf.Clamp01(volume);
            AudioListener.volume = isMuted ? 0f : masterVolume;
        }
    }
}

using UnityEngine;
using UnityEngine.Rendering;

namespace StoneThrowing
{
    public class QualityManager : MonoBehaviour
    {
        public static QualityManager Instance { get; private set; }

        [Header("Quality Levels")]
        public int currentQualityLevel = 2; // 0=Low, 1=Medium, 2=High, 3=Ultra
        public string[] qualityNames = { "LOW", "MEDIUM", "HIGH", "ULTRA" };

        [Header("FPS Target")]
        public int targetFPS = 60;
        public bool support90FPS = true;
        public bool support120FPS = true;
        public bool autoDetectFPS = true;

        [Header("Auto Quality")]
        public bool autoAdjustQuality = true;
        public float lowDeviceThreshold = 0.5f; // Tỷ lệ màn hình dưới đây coi là yếu

        [Header("Settings")]
        public bool motionBlurEnabled = false;
        public int particleCount = 100;
        public int waterQuality = 2;
        public int shadowQuality = 2;

        private bool isLowEndDevice = false;
        private FrameRateCounter fpsCounter;

        void Awake()
        {
            if (Instance != null && Instance != this)
            {
                Destroy(gameObject);
                return;
            }
            Instance = this;
            DontDestroyOnLoad(gameObject);
        }

        void Start()
        {
            DetectDevice();
            ApplyQualitySettings();
            SetupFrameRate();
        }

        void DetectDevice()
        {
            // Phát hiện thiết bị yếu dựa trên RAM và màn hình
            float screenRatio = (float)Screen.width / Screen.height;
            int systemMemory = SystemInfo.systemMemorySize;

            if (systemMemory < 2048 || screenRatio < lowDeviceThreshold)
            {
                isLowEndDevice = true;
                currentQualityLevel = 0;
                Debug.Log("Thiết bị yếu - tự động giảm chất lượng");
            }
        }

        public void ApplyQualitySettings()
        {
            QualitySettings.SetQualityLevel(currentQualityLevel, true);

            switch (currentQualityLevel)
            {
                case 0: // Low
                    particleCount = 30;
                    waterQuality = 1;
                    shadowQuality = 0;
                    motionBlurEnabled = false;
                    break;
                case 1: // Medium
                    particleCount = 60;
                    waterQuality = 2;
                    shadowQuality = 1;
                    motionBlurEnabled = false;
                    break;
                case 2: // High
                    particleCount = 100;
                    waterQuality = 3;
                    shadowQuality = 2;
                    motionBlurEnabled = true;
                    break;
                case 3: // Ultra
                    particleCount = 200;
                    waterQuality = 4;
                    shadowQuality = 2;
                    motionBlurEnabled = true;
                    break;
            }

            ApplyWaterQuality();
            ApplyParticleSettings();
            ApplyShadowSettings();
            ApplyMotionBlur(motionBlurEnabled);

            Debug.Log($"Chất lượng đồ họa: {qualityNames[currentQualityLevel]}");
        }

        public void SetQualityLevel(int level)
        {
            currentQualityLevel = Mathf.Clamp(level, 0, 3);
            ApplyQualitySettings();
        }

        public void SetupFrameRate()
        {
            if (autoDetectFPS)
            {
                int supportedMax = Screen.currentResolution.refreshRate;
                if (support120FPS && supportedMax >= 120)
                    targetFPS = 120;
                else if (support90FPS && supportedMax >= 90)
                    targetFPS = 90;
                else
                    targetFPS = 60;
            }

            Application.targetFrameRate = targetFPS;
            Debug.Log($"FPS mục tiêu: {targetFPS}");
        }

        void ApplyWaterQuality()
        {
            // Điều chỉnh shader water dựa trên chất lượng
            Shader waterShader = Shader.Find("Custom/WaterSurface");
            if (waterShader != null)
            {
                switch (waterQuality)
                {
                    case 0:
                        waterShader.maximumLOD = 200;
                        break;
                    case 1:
                        waterShader.maximumLOD = 300;
                        break;
                    case 2:
                        waterShader.maximumLOD = 400;
                        break;
                    case 3:
                        waterShader.maximumLOD = 500;
                        break;
                    case 4:
                        waterShader.maximumLOD = 600;
                        break;
                }
            }
        }

        void ApplyParticleSettings()
        {
            ParticleSystem[] allParticles = FindObjectsOfType<ParticleSystem>();
            foreach (var ps in allParticles)
            {
                var main = ps.main;
                main.maxParticles = particleCount;
            }
        }

        void ApplyShadowSettings()
        {
            switch (shadowQuality)
            {
                case 0:
                    QualitySettings.shadows = ShadowQuality.Disable;
                    break;
                case 1:
                    QualitySettings.shadows = ShadowQuality.HardOnly;
                    break;
                case 2:
                    QualitySettings.shadows = ShadowQuality.All;
                    break;
            }
            QualitySettings.shadowDistance = shadowQuality == 0 ? 0 : 50f;
        }

        public void EnableMotionBlur(bool enable)
        {
            motionBlurEnabled = enable;
            ApplyMotionBlur(enable);
        }

        void ApplyMotionBlur(bool enable)
        {
            // Tìm và bật/tắt Motion Blur effect
            var volume = FindObjectOfType<UnityEngine.Rendering.Volume>();
            if (volume != null)
            {
                if (volume.profile.TryGet(out UnityEngine.Rendering.PostProcessing.MotionBlur mb))
                {
                    mb.active = enable;
                }
            }
        }

        public void AutoReduceQualityIfNeeded(float currentFPS)
        {
            if (!autoAdjustQuality) return;

            if (currentFPS < 30f && currentQualityLevel > 0)
            {
                currentQualityLevel--;
                ApplyQualitySettings();
                Debug.Log($"Giảm chất lượng do FPS thấp: {qualityNames[currentQualityLevel]}");
            }
        }

        public bool IsLowEndDevice() => isLowEndDevice;
    }
}

using UnityEngine;
using System.Collections;

namespace StoneThrowing
{
    public class EnvironmentManager : MonoBehaviour
    {
        public static EnvironmentManager Instance { get; private set; }

        [Header("Day/Night Cycle")]
        public Light directionalLight;
        public float dayCycleDuration = 120f; // 2 phút cho một ngày
        public Gradient skyGradient;
        public Color dawnColor = new Color(1f, 0.6f, 0.3f);
        public Color dayColor = new Color(0.5f, 0.7f, 1f);
        public Color sunsetColor = new Color(1f, 0.4f, 0.2f);
        public Color nightColor = new Color(0.1f, 0.1f, 0.2f);

        [Header("Wind")]
        public float windStrength = 1f;
        public float windDirectionChangeTime = 30f;
        public Transform[] trees;
        public float treeSwayAmount = 0.1f;
        public float treeSwaySpeed = 2f;

        [Header("Clouds")]
        public Material cloudMaterial;
        public float cloudSpeed = 0.5f;
        public Vector2 cloudDirection = new Vector2(0.5f, 0.3f);

        [Header("Water")]
        public WaterSurface waterSurface;

        private float cycleTime = 0f;
        private Vector3 currentWindDirection;
        private float windTimer = 0f;

        void Awake()
        {
            if (Instance != null && Instance != this)
            {
                Destroy(gameObject);
                return;
            }
            Instance = this;
        }

        void Start()
        {
            currentWindDirection = Random.insideUnitCircle.normalized;
            SetupSkybox();
        }

        void Update()
        {
            UpdateDayNightCycle();
            UpdateWind();
            UpdateClouds();
            UpdateTrees();
        }

        void UpdateDayNightCycle()
        {
            cycleTime += Time.deltaTime / dayCycleDuration;
            if (cycleTime > 1f) cycleTime = 0f;

            // Thay đổi màu ánh sáng theo thời gian
            Color lightColor = Color.Lerp(dawnColor, dayColor, Mathf.PingPong(cycleTime, 1f));
            if (directionalLight != null)
            {
                directionalLight.color = lightColor;
                directionalLight.intensity = Mathf.Lerp(0.3f, 1.5f, Mathf.PingPong(cycleTime, 1f));
            }

            // Cập nhật Skybox
            RenderSettings.skybox.SetColor("_SkyTint", lightColor);
        }

        void SetupSkybox()
        {
            if (RenderSettings.skybox == null)
            {
                Material skyboxMat = new Material(Shader.Find("Skybox/Procedural"));
                RenderSettings.skybox = skyboxMat;
            }
        }

        void UpdateWind()
        {
            windTimer += Time.deltaTime;
            if (windTimer > windDirectionChangeTime)
            {
                currentWindDirection = Random.insideUnitCircle.normalized;
                windTimer = 0f;
            }
        }

        void UpdateTrees()
        {
            if (trees == null) return;

            float time = Time.time * treeSwaySpeed;
            foreach (var tree in trees)
            {
                if (tree == null) continue;

                // Mô phỏng gió làm cây lay động
                float sway = Mathf.Sin(time + tree.position.x) * treeSwayAmount * windStrength;
                tree.localRotation = Quaternion.Euler(0, sway * 10f, 0);
            }
        }

        void UpdateClouds()
        {
            if (cloudMaterial != null)
            {
                Vector2 offset = cloudMaterial.GetTextureOffset("_MainTex");
                offset += cloudDirection * cloudSpeed * Time.deltaTime;
                cloudMaterial.SetTextureOffset("_MainTex", offset);
            }
        }

        public void UpdateWaterWaves(float waveHeight, float waveSpeed)
        {
            if (waterSurface != null)
            {
                waterSurface.UpdateWaveParameters(waveHeight, waveSpeed);
            }
        }

        public Vector3 GetWindDirection() => currentWindDirection;
        public float GetWindStrength() => windStrength;
    }
}

using UnityEngine;

namespace StoneThrowing
{
    [RequireComponent(typeof(MeshRenderer))]
    [RequireComponent(typeof(MeshFilter))]
    public class WaterSurface : MonoBehaviour
    {
        [Header("Wave Settings")]
        public float waveHeight = 0.1f;
        public float waveSpeed = 1f;
        public float waveScale = 10f;
        public int waveOctaves = 4;

        [Header("Reflection")]
        public bool enableReflection = true;
        public LayerMask reflectionMask;
        public RenderTexture reflectionTexture;

        [Header("Caustics")]
        public Texture2D causticsTexture;
        public float causticsSpeed = 0.5f;
        public float causticsIntensity = 0.3f;

        [Header("Distortion")]
        public float distortionAmount = 0.05f;

        private Material waterMaterial;
        private Vector4[] waveParams;

        void Awake()
        {
            waterMaterial = GetComponent<MeshRenderer>().material;
            InitializeWaves();
        }

        void InitializeWaves()
        {
            waveParams = new Vector4[waveOctaves];
            for (int i = 0; i < waveOctaves; i++)
            {
                waveParams[i] = new Vector4(
                    Random.Range(0.5f, 2f),   // wavelength
                    Random.Range(0.5f, 2f),   // amplitude
                    Random.Range(0f, 360f),   // phase
                    Random.Range(0f, 1f)      // speed
                );
            }
        }

        void Update()
        {
            UpdateShaderParameters();
            UpdateCaustics();
        }

        void UpdateShaderParameters()
        {
            if (waterMaterial == null) return;

            waterMaterial.SetFloat("_WaveHeight", waveHeight);
            waterMaterial.SetFloat("_WaveSpeed", waveSpeed);
            waterMaterial.SetFloat("_WaveScale", waveScale);
            waterMaterial.SetFloat("_Time", Time.time);
            waterMaterial.SetFloat("_DistortionAmount", distortionAmount);

            // Cập nhật tham số sóng
            for (int i = 0; i < waveOctaves; i++)
            {
                waterMaterial.SetVector($"_Wave{i}", waveParams[i]);
            }
        }

        void UpdateCaustics()
        {
            if (causticsTexture != null && waterMaterial != null)
            {
                float offset = Time.time * causticsSpeed;
                waterMaterial.SetTexture("_CausticsTex", causticsTexture);
                waterMaterial.SetVector("_CausticsOffset", new Vector2(offset, offset * 0.5f));
                waterMaterial.SetFloat("_CausticsIntensity", causticsIntensity);
            }
        }

        public void UpdateWaveParameters(float height, float speed)
        {
            waveHeight = height;
            waveSpeed = speed;
        }

        public Vector3 GetWaterHeight(Vector3 worldPos)
        {
            // Trả về độ cao nước tại vị trí (dùng để kiểm tra đá chìm)
            float y = transform.position.y;
            for (int i = 0; i < waveOctaves; i++)
            {
                float wave = Mathf.Sin((worldPos.x + worldPos.z) * waveScale + Time.time * waveSpeed + waveParams[i].z) *
                             waveParams[i].y * waveHeight;
                y += wave;
            }
            return new Vector3(worldPos.x, y, worldPos.z);
        }
    }
}

using UnityEngine;
using UnityEngine.UI;
using TMPro;

namespace StoneThrowing
{
    public class FrameRateCounter : MonoBehaviour
    {
        public TextMeshProUGUI fpsText;
        public float updateInterval = 0.5f;

        private int frameCount = 0;
        private float timeLeft = 0f;
        private float fps = 0f;

        void Update()
        {
            timeLeft -= Time.deltaTime;
            frameCount++;

            if (timeLeft <= 0f)
            {
                fps = frameCount / updateInterval;
                if (fpsText != null)
                    fpsText.text = $"FPS: {Mathf.RoundToInt(fps)}";

                frameCount = 0;
                timeLeft = updateInterval;

                // Tự động giảm chất lượng nếu FPS quá thấp
                if (QualityManager.Instance != null)
                    QualityManager.Instance.AutoReduceQualityIfNeeded(fps);
            }
        }
    }
}

Shader "Custom/WaterSurface"
{
    Properties
    {
        _Color ("Màu Nước", Color) = (0.1, 0.4, 0.7, 1)
        _WaveHeight ("Chiều Cao Sóng", Float) = 0.1
        _WaveSpeed ("Tốc Độ Sóng", Float) = 1
        _WaveScale ("Kích Thước Sóng", Float) = 10
        _Time ("Thời gian", Float) = 0
        _DistortionAmount ("Biến Dạng", Float) = 0.05
        _DistortionStrength ("Cường Độ Biến Dạng", Float) = 0
        _ReflectionTex ("Ảnh Phản Chiếu", 2D) = "white" {}
        _RefractionTex ("Ảnh Gấp Sóng", 2D) = "white" {}
        _CausticsTex ("Ảnh Caustics", 2D) = "white" {}
        _CausticsOffset ("Vị Trí Caustics", Vector) = (0,0,0,0)
        _CausticsIntensity ("Cường Độ Caustics", Float) = 0.3
        _FoamColor ("Màu Bọt", Color) = (1,1,1,1)
        _FoamTiling ("O tiling Bọt", Float) = 5
    }

    SubShader
    {
        Tags { "RenderType"="Transparent" "Queue"="Transparent" }
        LOD 400

        Pass
        {
            Name "ForwardBase"
            Tags { "LightMode" = "ForwardBase" }

            CGPROGRAM
            #pragma vertex vert
            #pragma fragment frag
            #include "UnityCG.cginc"

            struct appdata
            {
                float4 vertex : POSITION;
                float2 uv : TEXCOORD0;
                float3 normal : NORMAL;
            };

            struct v2f
            {
                float2 uv : TEXCOORD0;
                float4 vertex : SV_POSITION;
                float3 worldPos : TEXCOORD1;
                float3 worldNormal : TEXCOORD2;
            };

            float4 _Color;
            float _WaveHeight;
            float _WaveSpeed;
            float _WaveScale;
            float _Time;
            float _DistortionAmount;
            float _DistortionStrength;
            float _CausticsIntensity;
            float4 _CausticsOffset;

            v2f vert (appdata v)
            {
                v2f o;

                // Gerstner waves approximation
                float3 pos = v.vertex;
                float3 worldPos = mul(unity_ObjectToWorld, float4(pos, 1));

                // Tính toán sóng đa lớp
                float wave = 0;
                for (int i = 0; i < 4; i++)
                {
                    float4 waveParam = _Wave0 + float4(i*4, 0, 0, 0); // Simplified
                    wave += sin((worldPos.x + worldPos.z) * _WaveScale + _Time * _WaveSpeed + waveParam.z) *
                            waveParam.y * _WaveHeight;
                }

                pos.y += wave;
                worldPos.y += wave;

                o.vertex = UnityObjectToClipPos(pos);
                o.uv = v.uv;
                o.worldPos = worldPos;
                o.worldNormal = v.normal;

                return o;
            }

            fixed4 frag (v2f i) : SV_Target
            {
                // Màu nước cơ bản
                fixed3 waterColor = _Color.rgb;

                // Phản chiếu bầu trời
                if (_DistortionStrength > 0)
                {
                    waterColor += tex2D(_ReflectionTex, i.uv + _DistortionStrength).rgb * 0.3;
                }

                // Caustics - ánh sáng khúc xạ dưới nước
                float2 causticsUV = i.uv * _FoamTiling + _CausticsOffset.xy;
                float caustics = tex2D(_CausticsTex, causticsUV).r * _CausticsIntensity;
                waterColor += caustics;

                // Biến dạng mặt nước
                fixed2 distortion = float2(
                    sin(_Time * 2 + i.uv.y * 10) * _DistortionAmount,
                    cos(_Time * 3 + i.uv.x * 10) * _DistortionAmount
                );

                fixed4 finalColor = fixed4(waterColor, _Color.a);
                finalColor.rgb *= 1 + caustics;

                // Fog / depth
                float depth = saturate(i.worldPos.y / 10);
                finalColor.rgb = lerp(finalColor.rgb, _Color.rgb, depth * 0.3);

                return finalColor;
            }
            ENDCG
        }
    }
}

Shader "Custom/WaterDistortion"
{
    Properties
    {
        _MainTex ("Texture", 2D) = "white" {}
        _DistortionStrength ("Cường Độ", Float) = 0.1
        _Center ("Tâm", Vector) = (0,0,0,0)
        _Radius ("Bán Kính", Float) = 1
        _Opacity ("Độ Trong Suối", Float) = 1
    }

    SubShader
    {
        Tags { "RenderType"="Transparent" "Queue"="Transparent" }
        LOD 200

        Pass
        {
            ZWrite Off
            Blend SrcAlpha OneMinusSrcAlpha

            CGPROGRAM
            #pragma vertex vert
            #pragma fragment frag
            #include "UnityCG.cginc"

            struct appdata
            {
                float4 vertex : POSITION;
                float2 uv : TEXCOORD0;
            };

            struct v2f
            {
                float2 uv : TEXCOORD0;
                float4 vertex : SV_POSITION;
            };

            sampler2D _MainTex;
            float _DistortionStrength;
            float4 _Center;
            float _Radius;
            float _Opacity;

            v2f vert (appdata v)
            {
                v2f o;
                o.vertex = UnityObjectToClipPos(v.vertex);
                o.uv = v.uv;
                return o;
            }

            fixed4 frag (v2f i) : SV_Target
            {
                // Tính khoảng cách từ tâm
                float2 centerUV = _Center.xy;
                float dist = distance(i.uv, centerUV);

                // Hiệu ứng vặn ngoài bên trong bán kính
                float distortion = 0;
                if (dist < _Radius)
                {
                    float t = 1 - dist / _Radius;
                    distortion = sin(_Time.y * 10 + dist * 20) * _DistortionStrength * t * t;
                }

                fixed2 distortedUV = i.uv + float2(distortion, -distortion);
                fixed4 col = tex2D(_MainTex, distortedUV);
                col.a *= _Opacity * (1 - dist / _Radius);

                return col;
            }
            ENDCG
        }
    }
}

Shader "Custom/WaterRipple"
{
    Properties
    {
        _Color ("Màu Sóng", Color) = (1,1,1,0.5)
        _Radius ("Bán Kính", Float) = 1
        _Opacity ("Độ Trong Suối", Float) = 1
        _Center ("Tâm", Vector) = (0,0,0,0)
    }

    SubShader
    {
        Tags { "RenderType"="Transparent" "Queue"="Transparent" }
        LOD 100

        Pass
        {
            ZWrite Off
            Blend SrcAlpha OneMinusSrcAlpha
            Cull Off

            CGPROGRAM
            #pragma vertex vert
            #pragma fragment frag
            #include "UnityCG.cginc"

            struct appdata
            {
                float4 vertex : POSITION;
                float2 uv : TEXCOORD0;
            };

            struct v2f
            {
                float2 uv : TEXCOORD0;
                float4 vertex : SV_POSITION;
                float worldDist : TEXCOORD1;
            };

            float4 _Color;
            float _Radius;
            float _Opacity;
            float4 _Center;

            v2f vert (appdata v)
            {
                v2f o;
                o.vertex = UnityObjectToClipPos(v.vertex);
                o.uv = v.uv;
                float3 worldPos = mul(unity_ObjectToWorld, v.vertex);
                o.worldDist = distance(worldPos.xz, _Center.xz);
                return o;
            }

            fixed4 frag (v2f i) : SV_Target
            {
                // Chỉ vẽ vòng sóng ở bán kính cụ thể
                float dist = i.worldDist;
                float ripple = smoothstep(_Radius - 0.1, _Radius, dist) *
                              smoothstep(_Radius, _Radius - 0.1, dist);

                fixed4 col = _Color;
                col.a = ripple * _Opacity;

                return col;
            }
            ENDCG
        }
    }
}

Shader "Custom/Stone"
{
    Properties
    {
        _Color ("Màu Đá", Color) = (0.7, 0.7, 0.7, 1)
        _MainTex ("Văn Bản Đá", 2D) = "white" {}
        _BumpMap ("Map Núi", 2D) = "bump" {}
        _Metallic ("Kim Loại", Range(0,1)) = 0.1
        _Smoothness ("Mịn", Range(0,1)) = 0.3
        _Size ("Kích Thước", Float) = 1
    }

    SubShader
    {
        Tags { "RenderType"="Opaque" }
        LOD 200

        Pass
        {
            Name "ForwardBase"
            Tags { "LightMode" = "ForwardBase" }

            CGPROGRAM
            #pragma vertex vert
            #pragma fragment frag
            #include "UnityCG.cginc"
            #include "Lighting.cginc"

            struct appdata
            {
                float4 vertex : POSITION;
                float2 uv : TEXCOORD0;
                float3 normal : NORMAL;
            };

            struct v2f
            {
                float2 uv : TEXCOORD0;
                float4 vertex : SV_POSITION;
                float3 worldNormal : TEXCOORD1;
                float3 worldPos : TEXCOORD2;
            };

            sampler2D _MainTex;
            sampler2D _BumpMap;
            float4 _Color;
            float _Metallic;
            float _Smoothness;
            float _Size;

            v2f vert (appdata v)
            {
                v2f o;
                o.vertex = UnityObjectToClipPos(v.vertex);
                o.uv = v.uv * _Size;
                o.worldNormal = UnityObjectToWorldNormal(v.normal);
                o.worldPos = mul(unity_ObjectToWorld, v.vertex).xyz;
                return o;
            }

            fixed4 frag (v2f i) : SV_Target
            {
                fixed4 texCol = tex2D(_MainTex, i.uv) * _Color;
                fixed3 normal = UnpackNormal(tex2D(_BumpMap, i.uv));
                normal = normalize(i.worldNormal);

                // Ánh sáng đơn giản
                fixed3 lightDir = normalize(_WorldSpaceLightPos0.xyz);
                fixed diff = max(0, dot(normal, lightDir));
                fixed3 ambient = fixed3(0.3, 0.3, 0.35);

                fixed3 result = ambient + texCol.rgb * diff * 0.7;
                result += texCol.rgb * _Metallic * 0.3;

                return fixed4(result, texCol.a * _Smoothness);
            }
            ENDCG
        }
    }
}

Shader "Custom/SplashParticle"
{
    Properties
    {
        _ParticleTex ("Vật Chất", 2D) = "white" {}
        _TintColor ("Màu", Color) = (1,1,1,1)
        _Softness ("Độ Mịn", Range(0,1)) = 1
    }

    Category
    {
        Tags { "Queue"="Transparent" "IgnoreProjector"="True" "RenderType"="Transparent" }
        Blend SrcAlpha One
        Cull Off Lighting Off ZWrite Off

        SubShader
        {
            Pass
            {
                Name "FORWARD"
                CGPROGRAM
                #pragma vertex vert
                #pragma fragment frag
                #include "UnityCG.cginc"

                struct appdata
                {
                    float4 vertex : POSITION;
                    fixed4 color : COLOR;
                    float2 texcoord : TEXCOORD0;
                };

                struct v2f
                {
                    fixed4 color : COLOR;
                    float2 texcoord : TEXCOORD0;
                    float4 vertex : SV_POSITION;
                };

                sampler2D _ParticleTex;
                fixed4 _TintColor;
                float _Softness;

                v2f vert (appdata v)
                {
                    v2f o;
                    o.vertex = UnityObjectToClipPos(v.vertex);
                    o.texcoord = v.texcoord;
                    o.color = v.color * _TintColor;
                    return o;
                }

                fixed4 frag (v2f i) : SV_Target
                {
                    fixed4 tex = tex2D(_ParticleTex, i.texcoord);
                    fixed4 col = tex * i.color;

                    // Làm mờ viền hạt nước
                    float alpha = tex.a * i.color.a;
                    alpha *= 1 - saturate(length(i.texcoord - 0.5) * 2 * _Softness);
                    col.a = alpha;

                    return col;
                }
                ENDCG
            }
        }
    }
}

